<template>
  <div>
    <StoreList :stores="stores" :loading="loading" :totalStores="totalStores" :downloadingExcel="downloadingExcel"
      :downloadingPdf="downloadingPdf" :canCreate="canCreate" :canRead="canRead" :canEdit="canEdit"
      :canDelete="canDelete" :canDownload="canDownload" :items-per-page="itemsPerPage" v-model:drawer="drawer"
      v-model:selectedFilter="selectedFilter" v-model:state="state" v-model:startDate="startDate"
      v-model:endDate="endDate" @open-form="openForm" @open-modal="openModal" @edit-store="openForm"
      @fetch-stores="fetchStores" @search-stores="searchStores" @update-items-per-page="updateItemsPerPage"
      @change-page="changePage" @download-excel="downloadExcel" @download-pdf="downloadPdf"
      @clear-filters="clearFilters" />

    <StoreForm v-model="form" :store="selectedStore" @saved="handleSaved" />

    <CommonModal v-model="modal" :itemId="selectedStore?.idStore || 0" :item="selectedStore?.storeName || ''"
      :action="action" moduleName="store" name="Unidad" gender="male"
      @action-completed="handleActionCompleted" />
  </div>
</template>

<script setup lang="ts">
import { ref, computed, onMounted } from 'vue';
import { useToast } from 'vue-toastification';
import { useStoreStore } from '@/stores/storeStore';
import { useAuthStore } from '@/stores/authStore';
import { Store } from '@/interfaces/storeInterface';
import { handleApiError, handleSilentError } from '@/helpers/errorHandler';
import { useFilters } from '@/composables/useFilters';
import { usePagination } from '@/composables/usePagination';
import StoreList from '@/components/Store/StoreList.vue';
import StoreForm from '@/components/Store/StoreForm.vue';
import CommonModal from '@/components/Common/CommonModal.vue';

const storeStore = useStoreStore();
const authStore  = useAuthStore();
const toast      = useToast();

const filterMap: Record<string, number> = { "Unidad": 1, "Encargado": 2, "Dirección": 3, "Ciudad": 4 };
const { selectedFilter, state, startDate, endDate, getFilterParams } = useFilters('Unidad', filterMap);

const search         = ref<string | null>(null);
const drawer         = ref(false);
const form           = ref(false);
const modal          = ref(false);
const selectedStore  = ref<Store | null>(null);
const action         = ref<0 | 1 | 2>(0);
const downloadingExcel = ref(false);
const downloadingPdf   = ref(false);

const { currentPage, itemsPerPage, updateItemsPerPage, changePage } = usePagination(
  (params) => {
    storeStore.fetchAll({
      pageNumber:  params.pageNumber,
      pageSize:    params.pageSize,
      ...getFilterParams(search.value),
    });
  }
);

const stores      = computed(() => storeStore.list);
const loading     = computed(() => storeStore.loading);
const totalStores = computed(() => storeStore.total);

const canCreate   = computed(() => authStore.hasPermission('unidades', 'crear'));
const canRead     = computed(() => authStore.hasPermission('unidades', 'leer'));
const canEdit     = computed(() => authStore.hasPermission('unidades', 'editar'));
const canDelete   = computed(() => authStore.hasPermission('unidades', 'eliminar'));
const canDownload = computed(() => authStore.hasPermission('unidades', 'descargar'));

const openModal = (payload: { store: Store; action: 0 | 1 | 2 }) => {
  selectedStore.value = payload.store;
  action.value        = payload.action;
  modal.value         = true;
};

const openForm = (storeData?: Store) => {
  selectedStore.value = storeData ? { ...storeData } : {
    idStore:       null,
    storeName:     '',
    manager:       '',
    address:       '',
    phoneNumber:   '',
    city:          '',
    email:         '',
    type:          '',
    profitMargin:  null,
    auditCreateDate: '',
    statusStore:   ''
  };
  form.value = true;
};

const fetchStores = async () => {
  try {
    await storeStore.fetchAll({
      pageNumber:  currentPage.value,
      pageSize:    itemsPerPage.value,
      stateFilter: state.value === 'Activos' ? 1 : 0,
    });
  } catch (error) {
    handleSilentError(error);
  }
};

const searchStores = async (params: {
  search: string | null;
  selectedFilter: string;
  state: string;
  startDate: Date | null;
  endDate: Date | null;
}) => {
  search.value          = params.search;
  selectedFilter.value  = params.selectedFilter;
  state.value           = params.state;
  startDate.value       = params.startDate;
  endDate.value         = params.endDate;
  currentPage.value     = 1;

  try {
    await storeStore.fetchAll({
      pageNumber: 1,
      pageSize:   itemsPerPage.value,
      ...getFilterParams(params.search),
    });
  } catch (error) {
    handleApiError(error, 'Error al buscar unidades');
  }
};

const clearFilters = () => {
  selectedFilter.value = 'Unidad';
  state.value          = 'Activos';
  startDate.value      = null;
  endDate.value        = null;
  search.value         = null;
  currentPage.value    = 1;
  fetchStores();
};

const downloadExcel = async (params: { search: string | null }) => {
  downloadingExcel.value = true;
  try {
    await storeStore.downloadExcel({
      pageNumber: currentPage.value,
      pageSize:   itemsPerPage.value,
      ...getFilterParams(params.search),
    });
    toast.success('Archivo descargado correctamente');
  } catch (error) {
    handleApiError(error, 'Error al descargar el archivo Excel');
  } finally {
    downloadingExcel.value = false;
  }
};

const downloadPdf = async (params: { search: string | null }) => {
  downloadingPdf.value = true;
  try {
    await storeStore.downloadPdf({
      pageNumber: currentPage.value,
      pageSize:   itemsPerPage.value,
      ...getFilterParams(params.search),
    });
    toast.success('Archivo PDF descargado correctamente');
  } catch (error) {
    handleApiError(error, 'Error al descargar el archivo PDF');
  } finally {
    downloadingPdf.value = false;
  }
};

const handleSaved = () => {
  fetchStores();
};

const handleActionCompleted = () => {
  fetchStores();
};

onMounted(() => {
  fetchStores();
});
</script>